def axis(s, a):
    (k, v, r) = (s['kappa_' + a], s['vel_' + a], s['robin_' + a])
    n = len(k)
    h = s['L' + a] / n
    A = np.zeros((n, n))
    for i in range(n):
        A[i, i] = abs(v[i]) / h
        for j in (i - 1, i + 1):
            if 0 <= j < n:
                diffusion = 2 / (1 / k[i] + 1 / k[j]) / h ** 2
                A[i, i] += diffusion
                A[i, j] = -diffusion - max(0.0, v[i] * np.sign(i - j)) / h
            else:
                A[i, i] += r * k[i] / (h * (k[i] + r * h / 2))
    return A
